global.schema:
type ExpenseReportState {
  expenses: [Expense!]!
}

type Expense {
  id: ID!
  memo: String!
  amountCents: Int!
  status: ExpenseStatus!
  approvedBy: String
}

enum ExpenseStatus {
  PENDING
  APPROVED
}

local.schema:
type ExpenseReportLocalState {
  reviewNotes: [ReviewNote!]!
}

type ReviewNote {
  expenseId: ID!
  note: String!
}

operations.schema:
input SubmitExpenseInput {
  id: ID!
  memo: String!
  amountCents: Int!
}

operations.reducer:
if (state.expenses.some((expense) => expense.id === action.input.id)) {
  throw new DuplicateExpenseError(`Expense ${action.input.id} already exists`);
}
state.expenses.push({
  id: action.input.id,
  memo: action.input.memo,
  amountCents: action.input.amountCents,
  status: "PENDING",
  approvedBy: null,
});

const expense = state.expenses.find(
  (candidate) => candidate.id === action.input.id,
);
if (!expense) {
  throw new ExpenseNotFoundError(`No expense ${action.input.id}`);
}
if (expense.status === "APPROVED") {
  throw new AlreadyApprovedError(`Expense ${action.input.id} is already approved`);
}
expense.status = "APPROVED";
expense.approvedBy = action.context?.signer?.user?.address ?? "anonymous";

operations.schema:
input AddReviewNoteInput {
  expenseId: ID!
  note: String!
}
